{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_mix_score AS WITH alloc_mix AS ( SELECT branch_code, order_date, UPPER(category) AS category, COALESCE(UPPER(style), \'SNITCH\') AS style, COALESCE(UPPER(meta1), \'N/A\') AS meta1, COALESCE(UPPER(meta2), \'N/A\') AS meta2, COALESCE(UPPER(meta3), \'N/A\') AS meta3, COUNT(DISTINCT sku_group) AS actual_options FROM snitch_db.maplemonk.fresh_allocation_tagged WHERE category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), alloc_mix_pct AS ( SELECT *, actual_options / NULLIF(SUM(actual_options) OVER (PARTITION BY branch_code, order_date), 0) AS alloc_mix_pct, SUM(actual_options) OVER (PARTITION BY branch_code, order_date) AS day_total_options, COUNT(*) OVER (PARTITION BY branch_code, order_date) AS day_total_combos FROM alloc_mix ), with_zone AS ( SELECT a.*, z.zone AS store_zone, CASE WHEN z.zone = \'NORTH\' THEN \'SOUTH\' WHEN z.zone = \'SOUTH\' THEN \'NORTH\' ELSE NULL END AS other_zone FROM alloc_mix_pct a LEFT JOIN snitch_db.maplemonk.store_zone_map z ON a.branch_code = z.branch_code ), compared AS ( SELECT a.branch_code, a.order_date, a.category, a.style, a.meta1, a.meta2, a.meta3, a.actual_options, a.alloc_mix_pct, a.day_total_options, a.day_total_combos, a.store_zone, COALESCE(s.sales_mix_blended_pct, 0) AS sales_mix_target_pct, CASE WHEN a.category IN (\'TROUSERS\', \'JEANS\') THEN COALESCE(wp.warehouse_mix_pct, wf.warehouse_mix_pct, 0) WHEN a.store_zone IS NOT NULL THEN COALESCE(wp.warehouse_mix_pct, 0) ELSE COALESCE(wa.warehouse_mix_pct, 0) END AS warehouse_mix_pct, LEAST( COALESCE(s.sales_mix_blended_pct, 0), CASE WHEN a.category IN (\'TROUSERS\', \'JEANS\') THEN COALESCE(wp.warehouse_mix_pct, wf.warehouse_mix_pct, 0) WHEN a.store_zone IS NOT NULL THEN COALESCE(wp.warehouse_mix_pct, 0) ELSE COALESCE(wa.warehouse_mix_pct, 0) END ) AS achievable_target_pct FROM with_zone a LEFT JOIN snitch_db.maplemonk.fresh_sales_mix_reference s ON a.branch_code = s.branch_code AND a.order_date = s.order_date AND a.category = s.category AND a.style = s.style AND a.meta1 = s.meta1 AND a.meta2 = s.meta2 AND a.meta3 = s.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wp ON wp.scope = a.store_zone AND a.category = wp.category AND a.style = wp.style AND a.meta1 = wp.meta1 AND a.meta2 = wp.meta2 AND a.meta3 = wp.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wf ON wf.scope = a.other_zone AND a.category = wf.category AND a.style = wf.style AND a.meta1 = wf.meta1 AND a.meta2 = wf.meta2 AND a.meta3 = wf.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wa ON wa.scope = \'ALL\' AND a.category = wa.category AND a.style = wa.style AND a.meta1 = wa.meta1 AND a.meta2 = wa.meta2 AND a.meta3 = wa.meta3 ), scored AS ( SELECT *, ABS(alloc_mix_pct - achievable_target_pct) AS mix_deviation FROM compared ), scored_tiered AS ( SELECT *, CASE WHEN mix_deviation <= 0.15 THEN \'Perfect\' WHEN mix_deviation <= 0.30 THEN \'Okay\' ELSE \'Poor\' END AS combo_deviation_tier FROM scored ), day_rollup AS ( SELECT branch_code, order_date, SUM(mix_deviation * achievable_target_pct) / NULLIF(SUM(achievable_target_pct), 0) AS weighted_mix_deviation FROM scored_tiered GROUP BY branch_code, order_date ) SELECT sc.*, dr.weighted_mix_deviation, CASE WHEN sc.day_total_options < 3 THEN \'Insufficient Volume\' WHEN dr.weighted_mix_deviation IS NULL THEN \'No Data\' WHEN dr.weighted_mix_deviation <= 0.15 THEN \'Perfect\' WHEN dr.weighted_mix_deviation <= 0.30 THEN \'Okay\' ELSE \'Poor\' END AS mix_score FROM scored_tiered sc LEFT JOIN day_rollup dr ON sc.branch_code = dr.branch_code AND sc.order_date = dr.order_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            